def english_defaults(apps, schema_editor):
    AIStyle = apps.get_model("management_api", "AIStyle")
    AIExample = apps.get_model("management_api", "AIExample")
    alias = schema_editor.connection.alias
    for item in STYLE_UPDATES:
        row = AIStyle.objects.using(alias).filter(code=item["code"]).first()
        if not row:
            continue
        changed = []
        for field, value in item["before"].items():
            if getattr(row, field) == value:
                setattr(row, field, item["after"][field])
                changed.append(field)
                translated = field + "_zh"
                if translated in item["after"] and not getattr(row, translated):
                    setattr(row, translated, item["after"][translated])
                    changed.append(translated)
        if changed:
            row.save(using=alias, update_fields=changed + ["updated_at"])
    for item in CASE_UPDATES:
        row = AIExample.objects.using(alias).filter(code=item["code"]).first()
        if not row:
            continue
        changed = []
        for field in ("name", "subject"):
            if getattr(row, field) == item["before"][field]:
                setattr(row, field, item["after"][field])
                changed.append(field)
                translated = field + "_zh"
                if not getattr(row, translated):
                    setattr(row, translated, item["after"][translated])
                    changed.append(translated)
        result = row.results.using(alias).filter(style__code=item["style"], image_path=item["image_path"], prompt=item["before"]["prompt"]).first()
        if result and row.original_path == item["original_path"] and result.prompt != item["after"]["prompt"]:
            result.prompt = item["after"]["prompt"]
            result.save(using=alias, update_fields=["prompt"])
            changed.append("revision")
        if changed:
            row.revision += 1
            row.save(using=alias, update_fields=list(set(changed + ["revision", "updated_at"])))


